import { TronWeb } from "tronweb";

// This app is deliberately mainnet-only. Network selection and node overrides are disabled.
const NETWORK = "mainnet";
const NODE = "https://api.trongrid.io";
const API_KEY = Deno.env.get("TRONGRID_API_KEY") ?? "";
const COOKIE_SECURE = Deno.env.get("AUTH_COOKIE_SECURE") !== "false";
const SESSION_TTL = 12 * 60 * 60 * 1000;
const CHALLENGE_TTL = 5 * 60 * 1000;
const kvPromise = Deno.openKv();
const verifier = new TronWeb({ fullHost: NODE });

const ICON = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#111318"/><path d="M10 14h28l16 14-26 25z" fill="none" stroke="#eb0029" stroke-width="5" stroke-linejoin="round"/><path d="M10 14l18 39 10-25z" fill="#eb0029" fill-opacity=".22"/><path d="M10 14l28 14 16 0" fill="none" stroke="#eb0029" stroke-width="3" stroke-linejoin="round"/></svg>`;
const MIME: Record<string, string> = {".html":"text/html; charset=utf-8",".svg":"image/svg+xml",".webmanifest":"application/manifest+json",".txt":"text/plain; charset=utf-8"};
const PAGE = String.raw`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#111318"><meta name="color-scheme" content="dark"><meta name="description" content="A secure TRON wallet workspace for connecting TronLink, verifying wallet ownership, exploring accounts, sending TRX and TRC-20 tokens, staking TRX, and tracking transactions."><meta name="application-name" content="TRON Console"><meta name="robots" content="index,follow"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="TRON Console"><link rel="canonical" href="{{ORIGIN}}/"><link rel="apple-touch-icon" href="/icon.svg"><meta property="og:type" content="website"><meta property="og:title" content="TRON Console — Wallet & Network"><meta property="og:description" content="Connect your TRON wallet, verify ownership, explore balances, send assets, stake TRX and track transactions."><meta property="og:image" content="{{ORIGIN}}/icon.svg"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="TRON Console"><meta name="twitter:description" content="Your TRON wallet workspace."><link rel="icon" type="image/svg+xml" href="/icon.svg"><link rel="manifest" href="/manifest.webmanifest"><title>TRON Console — Wallet & Network</title>
<style>
:root{color-scheme:dark;--bg:#0b0c10;--panel:#13151b;--panel2:#191c23;--line:#292d36;--muted:#9298a6;--text:#f5f6f8;--red:#eb0029;--red2:#ff3151;--green:#35d49a;--radius:18px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 88% 0%,#321019 0,transparent 32%),var(--bg);color:var(--text);min-height:100vh}button,input,select{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:11px;padding:11px 15px;color:var(--text);background:#20232b;transition:.18s}button:hover{border-color:#5a3039;transform:translateY(-1px)}button:disabled{opacity:.45;cursor:not-allowed;transform:none}.primary{background:var(--red);border-color:var(--red);color:white;font-weight:750}.primary:hover{background:var(--red2)}.quiet{background:transparent}.wrap{max-width:1180px;margin:auto;padding:22px 22px 50px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0 28px;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px}.brand img{width:42px;height:42px}.brand strong{letter-spacing:-.04em;font-size:19px}.brand small{display:block;color:var(--muted);font-size:11px;letter-spacing:.12em;text-transform:uppercase;margin-top:3px}.topactions{display:flex;align-items:center;gap:10px}.network{border:1px solid #3a2730;border-radius:99px;padding:8px 11px;font-size:12px;color:#ff8294;display:flex;gap:8px;align-items:center}.dot{width:7px;height:7px;background:var(--red);border-radius:100%;box-shadow:0 0 12px #eb002966}.hero{padding:38px 0 26px;display:flex;justify-content:space-between;align-items:end;gap:20px}.eyebrow{font-size:11px;letter-spacing:.17em;color:#ff7388;text-transform:uppercase;font-weight:800}.hero h1{font-size:clamp(31px,5vw,54px);letter-spacing:-.06em;line-height:1.03;margin:10px 0 12px}.hero p{max-width:620px;color:var(--muted);line-height:1.65;margin:0}.layout{display:grid;grid-template-columns:1.35fr .85fr;gap:16px}.stack{display:grid;gap:16px;align-content:start}.card{background:linear-gradient(150deg,#171920,#111318);border:1px solid var(--line);border-radius:var(--radius);padding:21px;min-width:0}.cardhead{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:17px}.cardhead h2{font-size:15px;margin:0;letter-spacing:-.02em}.cardhead span{font-size:11px;color:var(--muted)}.balance{background:radial-gradient(ellipse at 100% 0%,#49101e 0,transparent 45%),linear-gradient(135deg,#171920,#111318);position:relative;overflow:hidden}.balance:after{content:"TRON";position:absolute;right:10px;bottom:-35px;font-weight:950;font-size:108px;letter-spacing:-.09em;color:#ffffff05;pointer-events:none}.balanceval{font-size:clamp(30px,4vw,43px);letter-spacing:-.055em;font-weight:750;margin:7px 0}.balanceval small{font-size:14px;color:var(--muted);letter-spacing:0}.subline{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}.statrow{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:19px}.stat{border:1px solid var(--line);background:#0f1116;border-radius:12px;padding:12px}.stat small{color:var(--muted);display:block;font-size:11px}.stat strong{display:block;margin-top:6px;font-size:13px;overflow-wrap:anywhere}.formgrid{display:grid;gap:12px}.field{display:grid;gap:7px}.field label{font-size:12px;color:#c7cad2}.field input,.field select{width:100%;background:#0d0f14;color:var(--text);border:1px solid #30343e;border-radius:10px;padding:12px;outline:none;min-width:0}.field input:focus,.field select:focus{border-color:var(--red)}.field small{font-size:11px;color:var(--muted);line-height:1.45}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.status{border:1px solid var(--line);border-radius:12px;background:#0e1015;padding:13px;font-size:12px;color:var(--muted);line-height:1.55;overflow-wrap:anywhere}.status.ok{color:var(--green);border-color:#245343}.status.err{color:#ff8192;border-color:#61303a}.pill{border:1px solid var(--line);border-radius:99px;padding:5px 8px;color:var(--muted);font-size:10px}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px}.tabs button{font-size:12px;padding:9px 12px}.tabs button.active{border-color:#792033;background:#32121b;color:#ff9cab}.pane[hidden]{display:none}.txrow{border-bottom:1px solid var(--line);padding:12px 0;display:flex;justify-content:space-between;gap:12px;font-size:12px}.txrow:last-child{border:0}.txrow a{color:#ff8396;text-decoration:none}.muted{color:var(--muted)}.security{display:flex;gap:10px;align-items:start;color:var(--muted);font-size:12px;line-height:1.6}.shield{color:var(--green);font-size:18px}.footer{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap;padding:22px 0;color:#707582;font-size:11px}.footer a{color:#aab0bb}.toast{position:fixed;bottom:20px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#f5f6f8;color:#111318;padding:12px 17px;border-radius:12px;box-shadow:0 10px 40px #0008;font-size:13px;max-width:calc(100% - 24px);transition:.2s;z-index:9}.toast.show{opacity:1;transform:translate(-50%,0)}.loading{opacity:.6}@media(max-width:800px){.layout{grid-template-columns:1fr}.hero{align-items:start;flex-direction:column}.top{align-items:flex-start}.topactions{flex-wrap:wrap;justify-content:flex-end}.statrow{grid-template-columns:1fr 1fr 1fr}}@media(max-width:480px){.wrap{padding:12px 13px 32px}.top{gap:10px}.brand strong{font-size:16px}.brand img{width:36px;height:36px}.network{font-size:10px}.topactions{gap:6px}.topactions button{padding:9px;font-size:12px}.card{padding:16px}.two{grid-template-columns:1fr}.statrow{grid-template-columns:1fr 1fr}.hero{padding-top:28px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
</style></head><body><div class="wrap"><header class="top"><div class="brand"><img src="/icon.svg" alt="TRON Console icon"><div><strong>TRON Console</strong><small>Wallet · Network · Assets</small></div></div><div class="topactions"><div class="network"><i class="dot"></i><span id="netLabel">TRON MAINNET</span></div><button class="primary" id="connect">Connect wallet ↗</button></div></header>
<section class="hero"><div><div class="eyebrow">Your on-chain workspace</div><h1>One wallet.<br>Full control.</h1><p>Explore account data, authenticate wallet ownership, manage TRX and TRC-20 transfers, stake resources, and track transactions — with every transaction approved in your wallet.</p></div><span class="pill">NON-CUSTODIAL · TRONLINK</span></section>
<div class="layout"><div class="stack"><section class="card balance"><div class="cardhead"><h2>Wallet overview</h2><span id="walletState" class="pill">Not connected</span></div><div class="muted" style="font-size:12px">Available TRX balance</div><div class="balanceval" id="balance">— <small>TRX</small></div><div class="subline" id="address">Connect TronLink to load your account.</div><div class="actions"><button id="refresh" disabled>↻ Refresh balance</button><button id="signIn" disabled>Verify wallet ownership</button><button id="disconnect" class="quiet" disabled>Disconnect</button></div><div class="statrow"><div class="stat"><small>Network</small><strong id="networkStat">—</strong></div><div class="stat"><small>Energy</small><strong id="energy">—</strong></div><div class="stat"><small>Bandwidth</small><strong id="bandwidth">—</strong></div></div><div id="authStatus" class="status" style="margin-top:14px">Wallet authentication is separate from transaction approvals.</div></section>
<section class="card"><div class="cardhead"><h2>Asset operations</h2><span>Wallet-signed</span></div><div class="tabs"><button class="active" data-tab="trx">Send TRX</button><button data-tab="token">TRC-20 token</button><button data-tab="stake">Stake / unstake</button></div>
<div class="pane" id="pane-trx"><form id="trxForm" class="formgrid"><div class="field"><label for="trxTo">Recipient address</label><input id="trxTo" placeholder="T..." required autocomplete="off"></div><div class="field"><label for="trxAmount">Amount (TRX)</label><input id="trxAmount" type="number" min="0.000001" step="0.000001" placeholder="0.00" required></div><div class="status">Review the recipient and amount carefully. TronLink displays the final transaction confirmation.</div><button class="primary" type="submit" id="sendTrx" disabled>Review & send TRX ↗</button></form></div>
<div class="pane" id="pane-token" hidden><form id="tokenForm" class="formgrid"><div class="field"><label for="tokenContract">TRC-20 contract address</label><input id="tokenContract" placeholder="Verified token contract T..." required></div><div class="field"><label for="tokenTo">Recipient address</label><input id="tokenTo" placeholder="T..." required></div><div class="two"><div class="field"><label for="tokenAmount">Base-unit amount</label><input id="tokenAmount" inputmode="numeric" pattern="[0-9]+" placeholder="1000000" required><small>Integer only; token decimals vary.</small></div><div class="field"><label for="tokenDecimals">Token decimals (display only)</label><input id="tokenDecimals" type="number" min="0" max="30" value="6"></div></div><div class="status">Verify the token contract independently. This tool does not infer token decimals or guarantee that a token is legitimate.</div><button class="primary" type="submit" id="sendToken" disabled>Review & send token ↗</button></form></div>
<div class="pane" id="pane-stake" hidden><form id="stakeForm" class="formgrid"><div class="field"><label for="stakeAmount">Amount (TRX)</label><input id="stakeAmount" type="number" min="1" step="0.000001" placeholder="At least 1 TRX" required></div><div class="field"><label for="resource">Resource to receive</label><select id="resource"><option value="ENERGY">Energy</option><option value="BANDWIDTH">Bandwidth</option></select></div><button class="primary" type="submit" id="stake" disabled>Review Stake 2.0 ↗</button><button type="button" id="unstake" disabled>Request unfreeze</button><div class="status">Stake 2.0 availability and unfreeze rules depend on the active network and TronWeb provider. Always inspect the wallet transaction before confirming.</div></form></div></section>
<section class="card"><div class="cardhead"><h2>Transaction tracker</h2><span>On-chain status</span></div><form id="trackForm" class="formgrid"><div class="field"><label for="txid">Transaction ID</label><input id="txid" placeholder="64-character transaction ID" minlength="64" maxlength="64" required autocomplete="off"></div><button type="submit" id="track">Look up transaction</button></form><div id="txResult" class="status" style="margin-top:12px">Enter a transaction ID to inspect confirmation and receipt details.</div></section></div>
<aside class="stack"><section class="card"><div class="cardhead"><h2>Account explorer</h2><span>Read-only lookup</span></div><form id="lookupForm" class="formgrid"><div class="field"><label for="lookupAddress">TRON address</label><input id="lookupAddress" placeholder="T..." required autocomplete="off"></div><button type="submit" id="lookup">Inspect account ↗</button></form><div id="lookupResult" class="status" style="margin-top:12px">Look up any valid TRON Base58 address.</div></section>
<section class="card"><div class="cardhead"><h2>Session & security</h2><span id="sessionPill" class="pill">Signed out</span></div><div class="security"><span class="shield">◈</span><div><strong style="color:var(--text)">Keys stay in your wallet</strong><br>TRON Console never asks for a seed phrase or private key. Authentication signs a unique server challenge and creates a secure session. Transactions still require separate wallet approval.</div></div><div class="actions"><button id="checkSession" disabled>Check session</button><button id="logout" disabled>Sign out</button></div><div id="sessionInfo" class="status" style="margin-top:12px">Connect your wallet and verify ownership to start a session.</div></section>
<section class="card"><div class="cardhead"><h2>Network status</h2><span id="healthPill" class="pill">Checking</span></div><div id="health" class="status">Checking configured TRON network…</div><div class="actions"><a href="https://tronscan.org" target="_blank" rel="noopener noreferrer" style="color:#ff8294;font-size:12px">Open TronScan ↗</a><a href="https://www.tronlink.org/" target="_blank" rel="noopener noreferrer" style="color:#ff8294;font-size:12px">Get TronLink ↗</a></div></section></aside></div>
<footer class="footer"><span>TRON Console · Non-custodial wallet workspace</span><span>Network data via TRON node · <a href="/api/health">API health</a> · <a href="/manifest.webmanifest">App manifest</a></span></footer></div><div id="toast" class="toast"></div>
<script>
const $=id=>document.getElementById(id);const state={tronWeb:null,address:"",network:"",authenticated:false,session:null};let toastTimer;
function toast(s){$("toast").textContent=s;$("toast").classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").classList.remove("show"),3300)}
function status(id,msg,kind=""){const e=$(id);e.textContent=msg;e.className="status"+(kind?" "+kind:"")}
async function api(path,opts={}){const r=await fetch(path,{credentials:"same-origin",...opts,headers:{"Accept":"application/json",...(opts.body?{"Content-Type":"application/json"}:{}),...(opts.headers||{})}});const d=await r.json().catch(()=>({error:"Unexpected server response"}));if(!r.ok)throw new Error(d.error||"Request failed");return d}
function netName(){return "TRON Mainnet"}
function isMainnetWallet(tw){try{return new URL(String(tw?.fullNode?.host||"")).hostname==="api.trongrid.io"}catch{return false}}
function addrValid(tw,a){return !!tw&&typeof tw.isAddress==="function"&&tw.isAddress(a)}
function requireWallet(){if(!state.tronWeb||!state.address)throw Error("Connect TronLink first.");const now=state.tronWeb.defaultAddress?.base58;if(now!==state.address)throw Error("Wallet account changed. Reconnect and verify ownership.");if(!isMainnetWallet(state.tronWeb))throw Error("TRON Console accepts only the official TronGrid mainnet wallet node (api.trongrid.io). Switch TronLink to that node.");if(state.network!=="mainnet")throw Error("Mainnet verification is required. Reconnect your wallet.");return state.tronWeb}
function renderWallet(){const connected=!!state.address;$("walletState").textContent=connected?"Connected":"Not connected";$("walletState").className="pill";$("connect").textContent=connected?state.address.slice(0,6)+"…"+state.address.slice(-5):"Connect wallet ↗";$("address").textContent=connected?state.address:"Connect TronLink to load your account.";$("networkStat").textContent=connected?netName():"—";for(const id of ["refresh","signIn","disconnect","sendTrx","sendToken","stake","unstake"])$(id).disabled=!connected;$("checkSession").disabled=!state.authenticated;$("logout").disabled=!state.authenticated}
function disconnect(){fetch("/api/auth/logout",{method:"POST",credentials:"same-origin"}).catch(()=>{});state.tronWeb=null;state.address="";state.network="";state.authenticated=false;state.session=null;$("balance").innerHTML="— <small>TRX</small>";$("energy").textContent="—";$("bandwidth").textContent="—";$("sessionPill").textContent="Signed out";status("authStatus","Wallet disconnected.");status("sessionInfo","Connect your wallet and verify ownership to start a session.");renderWallet()}
async function connect(){try{if(!window.tronLink)throw Error("TronLink was not detected. Install or enable the wallet extension and reload.");const p=await window.tronLink.request({method:"tron_requestAccounts"});if(p?.code&&p.code!==200)throw Error(p.message||"Wallet permission was not granted.");const tw=window.tronWeb;if(!tw?.defaultAddress?.base58)throw Error("Unlock TronLink and select an account first.");if(!isMainnetWallet(tw))throw Error("TRON Console accepts only the official TronGrid mainnet wallet node (api.trongrid.io). Switch TronLink to that node.");const expected=(await api("/api/health")).network;if(expected!=="mainnet")throw Error("Server is not configured for TRON mainnet. Connection blocked.");state.tronWeb=tw;state.address=tw.defaultAddress.base58;state.network="mainnet";state.authenticated=false;renderWallet();await refresh();toast("Connected to TRON mainnet");}catch(e){state.tronWeb=null;state.address="";state.network="";state.authenticated=false;renderWallet();toast(e.message||"Wallet connection failed")}}
async function refresh(){try{const tw=requireWallet();const a=await tw.trx.getAccount(state.address);const sun=Number(a?.balance||0);$("balance").innerHTML=new Intl.NumberFormat(undefined,{maximumFractionDigits:6}).format(sun/1e6)+' <small>TRX</small>';$("energy").textContent=new Intl.NumberFormat().format(a?.account_resource?.energy_window_size||a?.account_resource?.energy_usage||0);$("bandwidth").textContent=new Intl.NumberFormat().format(a?.net_window_size||a?.net_usage||0);status("authStatus","Balance refreshed from the connected TRON node.","ok");}catch(e){status("authStatus",e.message||"Unable to refresh balance.","err")}}
async function signIn(){try{const tw=requireWallet();status("authStatus","Requesting a one-time server challenge…");const c=await api("/api/auth/challenge",{method:"POST",body:JSON.stringify({address:state.address})});if(!tw.trx?.signMessageV2)throw Error("This TronWeb provider does not support signMessageV2. Update TronLink.");const sig=await tw.trx.signMessageV2(c.message);const result=await api("/api/auth/verify",{method:"POST",body:JSON.stringify({address:state.address,nonce:c.nonce,signature:sig})});state.authenticated=true;state.session=result;$("sessionPill").textContent="Authenticated";status("authStatus","Server verified wallet ownership. Session expires "+result.expiresAtUtc+".","ok");status("sessionInfo","Authenticated address: "+result.address+" · Network: "+result.network+" · Expires: "+result.expiresAtUtc,"ok");renderWallet();toast("Wallet authenticated");}catch(e){state.authenticated=false;status("authStatus",e.message||"Authentication failed.","err");toast(e.message||"Authentication failed")}}
async function checkSession(){try{const s=await api("/api/auth/me");state.authenticated=true;state.session=s;$("sessionPill").textContent="Authenticated";status("sessionInfo","Authenticated address: "+s.address+" · Network: "+s.network+" · Expires: "+s.expiresAtUtc,"ok");renderWallet()}catch(e){state.authenticated=false;$("sessionPill").textContent="Signed out";status("sessionInfo",e.message||"No active session.");renderWallet()}}
async function logout(){try{await api("/api/auth/logout",{method:"POST"});}catch{}state.authenticated=false;state.session=null;$("sessionPill").textContent="Signed out";status("sessionInfo","You have signed out.");renderWallet();toast("Signed out")}
async function txWatch(id){$("txid").value=id;status("txResult","Submitted by wallet. Waiting for on-chain receipt…");for(let i=0;i<12;i++){await new Promise(r=>setTimeout(r,2500));try{const info=await api("/api/transaction?id="+encodeURIComponent(id));if(info.confirmed){const ok=info.receiptResult==="SUCCESS";status("txResult","Receipt: "+info.receiptResult+" · Block "+(info.blockNumber??"—")+" · Fee "+(info.feeSun??0)+" SUN · "+(ok?"Execution succeeded":"Transaction did not report SUCCESS"),ok?"ok":"err");return}}catch{}}status("txResult","Transaction was submitted, but a receipt is not available yet. Use the tracker to check again.");}
async function sendTrx(e){e.preventDefault();try{const tw=requireWallet(),to=$("trxTo").value.trim(),amount=Number($("trxAmount").value);if(!addrValid(tw,to))throw Error("Invalid TRON recipient address.");if(!Number.isFinite(amount)||amount<=0||amount>1e9)throw Error("Enter a valid positive TRX amount.");if(!confirm("Review transfer\n\nFrom: "+state.address+"\nTo: "+to+"\nAmount: "+amount+" TRX\n\nContinue to TronLink confirmation?"))return;const r=await tw.trx.sendTransaction(to,Math.round(amount*1e6));const id=r?.txid||r?.transaction?.txID;if(!id||r?.result===false)throw Error(r?.message||"Wallet did not return a transaction ID.");await txWatch(id)}catch(e){toast(e.message||"Transfer failed")}}
async function sendToken(e){e.preventDefault();try{const tw=requireWallet(),contract=$("tokenContract").value.trim(),to=$("tokenTo").value.trim(),amount=$("tokenAmount").value.trim();if(!addrValid(tw,contract)||!addrValid(tw,to))throw Error("Check the contract and recipient addresses.");if(!/^\d+$/.test(amount)||BigInt(amount)<=0n)throw Error("Enter a positive integer in token base units.");if(!confirm("Verify this token contract independently.\n\nContract: "+contract+"\nRecipient: "+to+"\nBase units: "+amount+"\n\nProceed to wallet confirmation?"))return;const token=await tw.contract().at(contract);const id=await token.transfer(to,amount).send({feeLimit:100000000,callValue:0,shouldPollResponse:false});if(typeof id!=="string"||id.length<32)throw Error("No transaction ID returned. Check wallet/network before retrying.");await txWatch(id)}catch(e){toast(e.message||"Token transfer failed")}}
async function stake(e){e.preventDefault();try{const tw=requireWallet();if(typeof tw.transactionBuilder?.freezeBalanceV2!=="function")throw Error("This TronWeb version does not support Stake 2.0 freezeBalanceV2.");const amount=Number($("stakeAmount").value),resource=$("resource").value;if(!Number.isFinite(amount)||amount<1)throw Error("Enter at least 1 TRX.");if(!confirm("Stake "+amount+" TRX for "+resource+"? Review the network and resource details in TronLink."))return;const tx=await tw.transactionBuilder.freezeBalanceV2(Math.round(amount*1e6),resource,state.address);const signed=await tw.trx.sign(tx);const sent=await tw.trx.sendRawTransaction(signed);if(!sent?.txid||sent.result===false)throw Error(sent?.message||"Stake transaction was not accepted.");await txWatch(sent.txid)}catch(e){toast(e.message||"Staking failed")}}
async function unStake(){try{const tw=requireWallet();if(typeof tw.transactionBuilder?.unfreezeBalanceV2!=="function")throw Error("Stake 2.0 unfreeze is not available in this TronWeb version.");const value=prompt("Amount to unfreeze in TRX");if(value===null)return;const amount=Number(value),resource=prompt("Resource: ENERGY or BANDWIDTH","ENERGY");if(!Number.isFinite(amount)||amount<1)throw Error("Enter a valid amount (minimum 1 TRX).");if(!["ENERGY","BANDWIDTH"].includes(resource))throw Error("Resource must be ENERGY or BANDWIDTH.");if(!confirm("Request unfreeze of "+amount+" TRX from "+resource+"? Waiting periods may apply."))return;const tx=await tw.transactionBuilder.unfreezeBalanceV2(Math.round(amount*1e6),resource,state.address);const signed=await tw.trx.sign(tx);const sent=await tw.trx.sendRawTransaction(signed);if(!sent?.txid||sent.result===false)throw Error("Unfreeze transaction was not accepted.");await txWatch(sent.txid)}catch(e){toast(e.message||"Unfreeze failed")}}
async function track(e){e.preventDefault();const id=$("txid").value.trim();if(!/^[a-fA-F0-9]{64}$/.test(id)){status("txResult","Enter a valid 64-character hexadecimal transaction ID.","err");return}try{const d=await api("/api/transaction?id="+encodeURIComponent(id));status("txResult",d.confirmed?"Receipt: "+d.receiptResult+" · Block "+(d.blockNumber??"—")+" · Fee "+(d.feeSun??0)+" SUN":"Transaction found but receipt is not yet available.");}catch(e){status("txResult",e.message||"Unable to query transaction.","err")}}
async function lookup(e){e.preventDefault();const a=$("lookupAddress").value.trim();try{const d=await api("/api/account?address="+encodeURIComponent(a));status("lookupResult","Address: "+d.address+"\nBalance: "+d.balanceTRX+" TRX ("+d.balanceSUN+" SUN)\nNetwork: "+d.network+"\nChecked: "+d.checkedAtUtc,"ok")}catch(e){status("lookupResult",e.message||"Account lookup failed.","err")}}
document.querySelectorAll("[data-tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-tab]").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".pane").forEach(p=>p.hidden=p.id!=="pane-"+b.dataset.tab)}));
$("connect").addEventListener("click",connect);$("refresh").addEventListener("click",refresh);$("signIn").addEventListener("click",signIn);$("disconnect").addEventListener("click",disconnect);$("checkSession").addEventListener("click",checkSession);$("logout").addEventListener("click",logout);$("trxForm").addEventListener("submit",sendTrx);$("tokenForm").addEventListener("submit",sendToken);$("stakeForm").addEventListener("submit",stake);$("unstake").addEventListener("click",unStake);$("trackForm").addEventListener("submit",track);$("lookupForm").addEventListener("submit",lookup);
window.addEventListener("message",ev=>{const a=ev?.data?.message?.action;if(a==="setAccount"||a==="accountsChanged"){if(state.address){disconnect();toast("Wallet account changed. Reconnect to continue.")}}if(a==="setNode"||a==="chainChanged"){if(state.address){disconnect();toast("Network changed. Reconnect and verify network.")}}});
async function health(){try{const d=await api("/api/health");$("netLabel").textContent="TRON MAINNET";$("healthPill").textContent="Online";status("health","Configured network: "+d.network+"\nNode: "+d.node+"\nAPI reachable.","ok")}catch(e){$("healthPill").textContent="Unavailable";status("health",e.message||"Network health check failed.","err")}}
checkSession();health();
</script></body></html>`;
